kwh = float(input())
if kwh <= 180:
    fee = kwh * 0.5
elif kwh <= 400:
    fee = 180 * 0.5 + (kwh - 180) * 0.55
else:
    fee = 180 * 0.5 + 220 * 0.55 + (kwh - 400) * 0.8
print(f'{fee:.2f}')

